<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Http\Resources\VehicleResource;use App\Models\Faq;use App\Models\HomepageSection;use App\Models\Location;use App\Models\Review;use App\Models\Service;use App\Models\Vehicle;
class HomeController extends Controller { public function __invoke(){ return response()->json(['data'=>['sections'=>HomepageSection::where('status','active')->orderBy('sort_order')->get(),'featured_vehicles'=>VehicleResource::collection(Vehicle::with(['brand','category','location','images','features'])->where('status','active')->where('featured',true)->orderBy('sort_order')->limit(6)->get()),'services'=>Service::where('status','active')->orderBy('sort_order')->limit(6)->get(),'locations'=>Location::where('status','active')->orderBy('sort_order')->get(),'reviews'=>Review::where('status','active')->orderBy('sort_order')->limit(8)->get(),'faqs'=>Faq::where('status','active')->orderBy('sort_order')->limit(8)->get()]]); } }
